#ifndef CALENDAR_UTIL_HPP
#define CALENDAR_UTIL_HPP

#include <string>
#include <ctime>

struct Date {
    int year = 0;
    int month = 0; // 1 - 12
    int day = 0;   // 1 - 31

    bool operator==(const Date& o) const {
        return year == o.year && month == o.month && day == o.day;
    }
    bool operator!=(const Date& o) const { return !(*this == o); }
    bool operator<(const Date& o) const;
    bool operator<=(const Date& o) const { return *this < o || *this == o; }
    bool operator>(const Date& o) const { return !(*this <= o); }
    bool operator>=(const Date& o) const { return !(*this < o); }
};

struct Time {
    int hour = 0;   // 0 - 23
    int minute = 0; // 0 - 59

    bool operator==(const Time& o) const {
        return hour == o.hour && minute == o.minute;
    }
    bool operator<(const Time& o) const {
        if (hour != o.hour) return hour < o.hour;
        return minute < o.minute;
    }
    bool operator<=(const Time& o) const { return *this < o || *this == o; }
};

struct DateTime {
    Date date;
    Time time;

    bool operator==(const DateTime& o) const {
        return date == o.date && time == o.time;
    }
    bool operator<(const DateTime& o) const {
        if (date != o.date) return date < o.date;
        return time < o.time;
    }
    bool operator<=(const DateTime& o) const { return *this < o || *this == o; }
};

