#include "calendar_util.hpp"
#include <cstdio>
#include <cstring>
#include <algorithm>
#include <sstream>
#include <iomanip>

bool is_leap_year(int year) {
    if (year % 400 == 0) return true;
    if (year % 100 == 0) return false;
    return year % 4 == 0;
}

int days_in_month(int month, int year) {
    static const int days[13] = {0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    if (month == 2 && is_leap_year(year)) return 29;
    if (month >= 1 && month <= 12) return days[month];
    return 30;
}

int date_to_days(Date d) {
    int y = d.year;
    int m = d.month;
    int day = d.day;
    if (m <= 2) {
        y -= 1;
        m += 12;
    }
    int era = (y >= 0 ? y : y - 399) / 400;
    unsigned yoe = static_cast<unsigned>(y - era * 400);
    unsigned doy = (153 * (m - 3) + 2) / 5 + day - 1;
    unsigned doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    return era * 146097 + static_cast<int>(doe) - 719468;
}

Date days_to_date(int days) {
    int z = days + 719468;
    int era = (z >= 0 ? z : z - 146096) / 146097;
    unsigned doe = static_cast<unsigned>(z - era * 146097);
    unsigned yoe = (doe - doe/1460 + doe/36524 - doe/146096) / 365;
    int y = static_cast<int>(yoe) + era * 400;
    unsigned doy = doe - (365*yoe + yoe/4 - yoe/100);
    unsigned mp = (5*doy + 2)/153;
    unsigned d = doy - (153*mp + 2)/5 + 1;
    unsigned m = mp < 10 ? mp + 3 : mp - 9;
    if (m <= 2) y += 1;
    return Date{y, static_cast<int>(m), static_cast<int>(d)};
}

bool Date::operator<(const Date& o) const {
    return date_to_days(*this) < date_to_days(o);
}

int day_of_week(Date d) {
    int days = date_to_days(d);
    int dow = (days + 4) % 7; // 1970-01-01 was Thursday (4)
    if (dow < 0) dow += 7;
    return dow;
}

Date current_date() {
    time_t t = time(nullptr);
    struct tm tm_buf;
    localtime_r(&t, &tm_buf);
    return Date{tm_buf.tm_year + 1900, tm_buf.tm_mon + 1, tm_buf.tm_mday};
}

DateTime current_datetime() {
    time_t t = time(nullptr);
    struct tm tm_buf;
    localtime_r(&t, &tm_buf);
    return DateTime{Date{tm_buf.tm_year + 1900, tm_buf.tm_mon + 1, tm_buf.tm_mday},
                    Time{tm_buf.tm_hour, tm_buf.tm_min}};
}

