#include "db.hpp"
#include "sha1.hpp"
#include <fstream>
#include <sstream>
#include <iostream>
#include <filesystem>
#include <algorithm>
#include <set>

namespace fs = std::filesystem;

void Database::set_paths(const std::string& d_dir, const std::string& c_dir, const std::string& cal_file) {
    datadir = d_dir;
    confdir = c_dir;
    calendar_file = cal_file;
}

bool Database::load_all() {
    todos.clear();
    events.clear();
    apts.clear();

    std::string todo_path = datadir + "/todo";
    std::string apts_path = calendar_file.empty() ? (datadir + "/apts") : calendar_file;

    if (fs::exists(todo_path)) {
        load_todo(todo_path);
    }
    if (fs::exists(apts_path)) {
        load_apts(apts_path);
    }
    return true;
}

bool Database::save_all() {
    if (read_only) return true;
    if (!datadir.empty()) {
        fs::create_directories(datadir);
        fs::create_directories(datadir + "/notes");
    }
    if (!confdir.empty()) {
        fs::create_directories(confdir);
        fs::create_directories(confdir + "/hooks");
    }

    std::string todo_path = datadir + "/todo";
    std::string apts_path = calendar_file.empty() ? (datadir + "/apts") : calendar_file;

    save_todo(todo_path);
    save_apts(apts_path);
    return true;
}

bool Database::load_todo(const std::string& filepath) {
    std::ifstream ifs(filepath);
    if (!ifs.is_open()) return false;

    std::string line;
    while (std::getline(ifs, line)) {
        if (line.empty()) continue;
        TodoItem item;
        item.raw_line = line;
        item.hash = compute_sha1(line);

        size_t p_open = line.find('[');
        size_t p_close = line.find(']');
        if (p_open != std::string::npos && p_close != std::string::npos && p_close > p_open) {
            std::string p_str = line.substr(p_open + 1, p_close - p_open - 1);
            if (!p_str.empty() && p_str[0] == '-') {
                item.completed = true;
                item.priority = std::abs(std::stoi(p_str));
            } else {
                item.completed = false;
                item.priority = std::abs(std::stoi(p_str));
            }

            size_t rest_pos = p_close + 1;
            if (rest_pos < line.size() && line[rest_pos] == '>') {
                size_t space_pos = line.find(' ', rest_pos);
                if (space_pos != std::string::npos) {
                    item.note_hash = line.substr(rest_pos + 1, space_pos - rest_pos - 1);
                    item.mesg = line.substr(space_pos + 1);
                } else {
                    item.mesg = line.substr(rest_pos + 1);
                }
            } else {
                if (rest_pos < line.size() && line[rest_pos] == ' ') rest_pos++;
                item.mesg = line.substr(rest_pos);
            }
            todos.push_back(item);
        }
    }
    return true;
}

bool Database::load_apts(const std::string& filepath) {
    std::ifstream ifs(filepath);
    if (!ifs.is_open()) return false;

    std::string line;
    while (std::getline(ifs, line)) {
        if (line.empty()) continue;

        if (line.find('@') != std::string::npos) {
            // Appointment
            AptItem item;
