cat << 'EOF' > src/filter_format.cpp
#include "filter_format.hpp"
#include <sstream>
#include <iostream>
#include <iomanip>

void FilterOpts::set_type_filter(const std::string& type_str) {
    if (!filter_type_specified) {
        type_event = false;
        type_apt = false;
        type_recur_event = false;
        type_recur_apt = false;
        type_todo = false;
        filter_type_specified = true;
    }

    std::stringstream ss(type_str);
    std::string token;
    while (std::getline(ss, token, ',')) {
        if (token == "event") type_event = true;
        else if (token == "apt") type_apt = true;
        else if (token == "recur-event") type_recur_event = true;
        else if (token == "recur-apt") type_recur_apt = true;
        else if (token == "todo") type_todo = true;
        else if (token == "cal") {
            type_event = true;
            type_apt = true;
            type_recur_event = true;
            type_recur_apt = true;
        }
    }
}

bool FilterOpts::match_todo(const TodoItem& item) const {
    if (!type_todo) return false;
    if (priority != -1 && item.priority != priority) return false;
    if (completed && !item.completed) return false;
    if (uncompleted && item.completed) return false;

    if (!pattern.empty()) {
        std::regex re(pattern, std::regex_constants::extended);
        if (!std::regex_search(item.mesg, re)) return false;
    }

    if (!hash_str.empty()) {
        bool match = (item.hash.rfind(hash_str, 0) == 0);
        if (hash_invert && match) return false;
        if (!hash_invert && !match) return false;
    }

    return true;
}

bool FilterOpts::match_event(const EventItem& item) const {
    if (item.recur.active()) {
        if (!type_recur_event) return false;
    } else {
        if (!type_event) return false;
    }

    if (!pattern.empty()) {
        std::regex re(pattern, std::regex_constants::extended);
        if (!std::regex_search(item.mesg, re)) return false;
    }

    if (!hash_str.empty()) {
        bool match = (item.hash.rfind(hash_str, 0) == 0);
        if (hash_invert && match) return false;
        if (!hash_invert && !match) return false;
    }

    if (start_from.year > 0 && item.day < start_from) return false;
    if (start_to.year > 0 && item.day > start_to) return false;
    if (start_after.year > 0 && item.day <= start_after) return false;
    if (start_before.year > 0 && item.day >= start_before) return false;

    return true;
}

bool FilterOpts::match_apt(const AptItem& item) const {
    if (item.recur.active()) {
        if (!type_recur_apt) return false;
    } else {
        if (!type_apt) return false;
    }

    if (!pattern.empty()) {
        std::regex re(pattern, std::regex_constants::extended);
        if (!std::regex_search(item.mesg, re)) return false;
    }

    if (!hash_str.empty()) {
        bool match = (item.hash.rfind(hash_str, 0) == 0);
        if (hash_invert && match) return false;
        if (!hash_invert && !match) return false;
    }

    if (start_from.year > 0 && item.start.date < start_from) return false;
    if (start_to.year > 0 && item.start.date > start_to) return false;
    if (start_after.year > 0 && item.start.date <= start_after) return false;
    if (start_before.year > 0 && item.start.date >= start_before) return false;

    if (end_from.year > 0 && item.end.date < end_from) return false;
    if (end_to.year > 0 && item.end.date > end_to) return false;
    if (end_after.year > 0 && item.end.date <= end_after) return false;
    if (end_before.year > 0 && item.end.date >= end_before) return false;

    return true;
}

std::string format_todo(const TodoItem& item, const std::string& fmt, const Database& db) {
    if (fmt == "%(raw)") return item.raw_line + "\n";
    std::string res;
    for (size_t i = 0; i < fmt.size(); ++i) {
        if (fmt[i] == '%' && i + 1 < fmt.size()) {
            char c = fmt[i + 1];
            if (c == 'p') { res += std::to_string(item.priority); i++; }
            else if (c == 'm') { res += item.mesg; i++; }
            else if (c == 'n') { res += item.note_hash; i++; }
            else if (c == 'N') { res += db.get_note(item.note_hash); i++; }
            else if (fmt.substr(i, 7) == "%(hash)") { res += item.hash; i += 6; }
            else if (fmt.substr(i, 6) == "%(raw)") { res += item.raw_line; i += 5; }
            else { res += fmt[i]; }
        } else {
            res += fmt[i];
        }
    }
    return res;
}

std::string format_event(const EventItem& item, const std::string& fmt, const Database& db) {
    if (fmt == "%(raw)") return item.raw_line + "\n";
    std::string res;
    for (size_t i = 0; i < fmt.size(); ++i) {
        if (fmt[i] == '%' && i + 1 < fmt.size()) {
            char c = fmt[i + 1];
            if (c == 'm') { res += item.mesg; i++; }
            else if (c == 'n') { res += item.note_hash; i++; }
            else if (c == 'N') { res += db.get_note(item.note_hash); i++; }
            else if (fmt.substr(i, 7) == "%(hash)") { res += item.hash; i += 6; }
            else if (fmt.substr(i, 6) == "%(raw)") { res += item.raw_line; i += 5; }
            else { res += fmt[i]; }
        } else {
            res += fmt[i];
        }
    }
    return res;
}

std::string format_apt(const AptItem& item, Date current_day, const std::string& fmt, const Database& db) {
    if (fmt == "%(raw)") return item.raw_line + "\n";
    std::string res;

    std::string start_s = (item.start.date == current_day) ? format_time(item.start.time) : "..:..";
    std::string end_s = (item.end.date == current_day) ? format_time(item.end.time) : "..:..";

    for (size_t i = 0; i < fmt.size(); ++i) {
        if (fmt[i] == '\\' && i + 1 < fmt.size()) {
            if (fmt[i + 1] == 'n') { res += '\n'; i++; }
            else if (fmt[i + 1] == 't') { res += '\t'; i++; }
            else { res += fmt[i]; }
        } else if (fmt[i] == '%' && i + 1 < fmt.size()) {
            char c = fmt[i + 1];
            if (c == 'S') { res += start_s; i++; }
            else if (c == 'E') { res += end_s; i++; }
