cat << 'EOF' > src/ical.cpp
#include "ical.hpp"
#include <fstream>
#include <sstream>
#include <iostream>
#include <iomanip>
#include <algorithm>

bool import_ical(const std::string& filepath, Database& db, ImportReport& report, bool dump_imported, const FormatOpts& fmt_opts, bool quiet) {
    std::ifstream ifs(filepath);
    if (!ifs.is_open()) {
        std::cerr << "io.c: 1278: FATAL ERROR: the input file cannot be accessed, Aborting...\n";
        return false;
    }

    std::string line;
    std::vector<std::string> lines;
    while (std::getline(ifs, line)) {
        if (!line.empty() && line.back() == '\r') line.pop_back();
        lines.push_back(line);
    }
    report.lines_read = static_cast<int>(lines.size());

    enum Block { NONE, VEVENT, VTODO };
    Block cur_block = NONE;

    std::string summary, description, dtstart, dtend, duration, rrule;
    int priority = 0;

    for (const auto& l : lines) {
        if (l == "BEGIN:VEVENT") {
            cur_block = VEVENT;
            summary.clear(); description.clear(); dtstart.clear(); dtend.clear(); duration.clear(); rrule.clear();
        } else if (l == "END:VEVENT" && cur_block == VEVENT) {
            cur_block = NONE;
            // Parse event or apt
            if (!dtstart.empty()) {
                bool is_all_day = (dtstart.find("VALUE=DATE") != std::string::npos || dtstart.find('T') == std::string::npos);
                std::string start_val = dtstart;
                size_t colon = start_val.find(':');
                if (colon != std::string::npos) start_val = start_val.substr(colon + 1);

                if (is_all_day) {
                    EventItem item;
                    if (start_val.size() >= 8) {
                        item.day.year = std::stoi(start_val.substr(0, 4));
                        item.day.month = std::stoi(start_val.substr(4, 2));
                        item.day.day = std::stoi(start_val.substr(6, 2));
                    }
                    item.mesg = summary;
                    if (!description.empty()) {
                        db.save_note(description, item.note_hash);
                    }
                    item.raw_line = item.to_raw_line(db.input_fmt);
                    item.hash = compute_sha1(item.raw_line);
                    db.events.push_back(item);
                    report.events++;
                    if (dump_imported) {
                        std::cout << format_event(item, fmt_opts.fmt_event, db);
                    }
                } else {
                    AptItem item;
                    size_t t_pos = start_val.find('T');
                    if (t_pos != std::string::npos && start_val.size() >= t_pos + 5) {
                        item.start.date.year = std::stoi(start_val.substr(0, 4));
                        item.start.date.month = std::stoi(start_val.substr(4, 2));
                        item.start.date.day = std::stoi(start_val.substr(6, 2));
                        item.start.time.hour = std::stoi(start_val.substr(t_pos + 1, 2));
                        item.start.time.minute = std::stoi(start_val.substr(t_pos + 3, 2));
                    }
                    item.end = item.start; // Default end time
                    if (!dtend.empty()) {
                        std::string end_val = dtend;
                        size_t c = end_val.find(':');
                        if (c != std::string::npos) end_val = end_val.substr(c + 1);
                        size_t end_t = end_val.find('T');
                        if (end_t != std::string::npos && end_val.size() >= end_t + 5) {
                            item.end.date.year = std::stoi(end_val.substr(0, 4));
                            item.end.date.month = std::stoi(end_val.substr(4, 2));
                            item.end.date.day = std::stoi(end_val.substr(6, 2));
                            item.end.time.hour = std::stoi(end_val.substr(end_t + 1, 2));
                            item.end.time.minute = std::stoi(end_val.substr(end_t + 3, 2));
                        }
                    }
                    item.mesg = summary;
                    if (!description.empty()) {
                        db.save_note(description, item.note_hash);
                    }
                    item.raw_line = item.to_raw_line(db.input_fmt);
                    item.hash = compute_sha1(item.raw_line);
                    db.apts.push_back(item);
                    report.apps++;
                    if (dump_imported) {
                        std::cout << format_apt(item, item.start.date, fmt_opts.fmt_apt, db);
                    }
                }
            } else {
                report.skipped++;
            }
        } else if (l == "BEGIN:VTODO") {
            cur_block = VTODO;
            summary.clear(); description.clear(); priority = 0;
