        char dtbuf[32];
        snprintf(dtbuf, sizeof(dtbuf), "DTSTART:%04d%02d%02dT%02d%02d00\n",
                 item.start.date.year, item.start.date.month, item.start.date.day,
                 item.start.time.hour, item.start.time.minute);
        os << dtbuf;

        int dur_min = (date_to_days(item.end.date) - date_to_days(item.start.date)) * 1440 +
                      (item.end.time.hour * 60 + item.end.time.minute) -
                      (item.start.time.hour * 60 + item.start.time.minute);
        int d = dur_min / 1440;
        int h = (dur_min % 1440) / 60;
        int m = dur_min % 60;
        char durbuf[32];
        snprintf(durbuf, sizeof(durbuf), "DURATION:P%dDT%dH%dMS0S\n", d, h, m);
        os << durbuf;
        os << "SUMMARY:" << item.mesg << "\n";
        if (!item.note_hash.empty()) {
            std::string note = db.get_note(item.note_hash);
            if (!note.empty()) os << "DESCRIPTION:" << note << "\n";
        }
        os << "END:VEVENT\n";
    }

    for (const auto& item : db.todos) {
        if (!filters.match_todo(item)) continue;
        os << "BEGIN:VTODO\n";
        os << "PRIORITY:" << item.priority << "\n";
        os << "SUMMARY:" << item.mesg << "\n";
        if (!item.note_hash.empty()) {
            std::string note = db.get_note(item.note_hash);
            if (!note.empty()) os << "DESCRIPTION:" << note << "\n";
        }
        os << "END:VTODO\n";
    }

    os << "END:VCALENDAR\n";
}

void export_pcal(const Database& db, const FilterOpts& filters, std::ostream& os) {
    os << "# calcurse pcal export\n\n";
    os << "# =======\n# options\n# =======\n";
    os << "opt -A -K -l -m -F Monday\n";
    os << "# Display week number (i.e. 1-52) on every Monday\n";
    os << "all monday in all week %w\n\n\n";
    os << "# =============\n# Recur. Events\n# =============\n";
    os << "# (pcal does not support from..until dates specification\n\n";
    os << "# ======\n# Events\n# ======\n\n\n";
    os << "# ==============\n# Recur. Apoints\n# ==============\n";
    os << "# (pcal does not support from..until dates specification\n\n";
    os << "# ============\n# Appointments\n# ============\n";

    static const char* month_names[] = {"", "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"};

    for (const auto& item : db.apts) {
        if (!filters.match_apt(item)) continue;
        char buf[128];
        snprintf(buf, sizeof(buf), "%s %d  (%02d:%02d -> %02d:%02d) %s\n",
                 month_names[item.start.date.month], item.start.date.day,
                 item.start.time.hour, item.start.time.minute,
                 item.end.time.hour, item.end.time.minute,
                 item.mesg.c_str());
        os << buf;
    }

    os << "\n#\n# Todos\n#\n\n";
}
EOF"}

