#include "daemon.hpp"
#include <iostream>
#include <fstream>
#include <filesystem>
#include <unistd.h>
#include <csignal>
#include <sys/types.h>
#include <sys/stat.h>

namespace fs = std::filesystem;

static std::string pid_filepath;
static std::string log_filepath;
static bool logging_enabled = false;

static void log_message(const std::string& msg) {
    if (!logging_enabled || log_filepath.empty()) return;
    std::ofstream ofs(log_filepath, std::ios::app);
    if (ofs.is_open()) {
        ofs << msg << "\n";
    }
}

static void sig_handler(int sig) {
    if (!pid_filepath.empty()) {
        fs::remove(pid_filepath);
    }
    time_t now = time(nullptr);
    char buf[128];
    struct tm tm_buf;
    localtime_r(&now, &tm_buf);
    strftime(buf, sizeof(buf), "terminated at %a %b %d %H:%M:%S %Y", &tm_buf);
    log_message(std::string(buf) + " with signal " + std::to_string(sig));
    exit(0);
}

int check_status(const Database& db) {
    std::string datadir = db.datadir;
    std::string calc_pid_file = datadir + "/.calcurse.pid";
    std::string daemon_pid_file = datadir + "/.daemon.pid";

    std::string calc_pid, daemon_pid;
    bool calc_running = false;
    bool daemon_running = false;

    if (fs::exists(calc_pid_file)) {
        std::ifstream ifs(calc_pid_file);
        if (ifs >> calc_pid) calc_running = true;
    }
    if (fs::exists(daemon_pid_file)) {
        std::ifstream ifs(daemon_pid_file);
        if (ifs >> daemon_pid) daemon_running = true;
    }

    if (calc_running && daemon_running) {
        std::cerr << "args.c: 181: Error: both calcurse (pid: " << calc_pid
                  << ") and its daemon (pid: " << daemon_pid
                  << ")\nseem to be running at the same time!\n"
                  << "Please check manually and restart calcurse.\n\n";
        return 1;
    }

    if (calc_running) {
        std::cout << "calcurse is running (pid " << calc_pid << ")\n";
        return 0;
    }

    if (daemon_running) {
        std::cout << "calcurse is running in background (pid " << daemon_pid << ")\n";
        return 0;
    }

    std::cout << "calcurse is not running\n";
    return 0;
}

void run_daemon(Database& db, const Config& cfg) {
    if (!cfg.daemon_enable) return;

    pid_t pid = fork();
    if (pid < 0) return;
    if (pid > 0) exit(0); // Parent exits

    setsid();
    umask(0);

    pid_filepath = db.datadir + "/.daemon.pid";
    log_filepath = db.datadir + "/daemon.log";
    logging_enabled = cfg.daemon_log;

    std::ofstream ofs(pid_filepath);
    if (ofs.is_open()) {
        ofs << getpid() << "\n";
    }

    signal(SIGTERM, sig_handler);
    signal(SIGINT, sig_handler);

    time_t start_time = time(nullptr);
    char buf[128];
    struct tm tm_buf;
    localtime_r(&start_time, &tm_buf);
    strftime(buf, sizeof(buf), "started at %a %b %d %H:%M:%S %Y", &tm_buf);
    log_message(buf);

    while (true) {
        time_t now = time(nullptr);
        localtime_r(&now, &tm_buf);
        strftime(buf, sizeof(buf), "sleeping at %a %b %d %H:%M:%S %Y for 60 seconds", &tm_buf);
        log_message(buf);
        sleep(60);
    }
}
EOF"}

