#include "tui.hpp"
#include "calendar_util.hpp"
#include <ncurses.h>
#include <cstring>
#include <string>
#include <vector>
#include <algorithm>
#include <fstream>
#include <unistd.h>
#include <sys/wait.h>

enum ActivePanel { PANEL_CALENDAR = 0, PANEL_APTS = 1, PANEL_TODO = 2 };

struct TuiState {
    ActivePanel active_panel = PANEL_CALENDAR;
    Date sel_date;
    int sel_apt_idx = 0;
    int sel_todo_idx = 0;
    int cal_month = 0;
    int cal_year = 0;
    bool quit = false;
};

static void draw_border_title(WINDOW* win, const std::string& title, bool active) {
    wattron(win, active ? A_BOLD : A_NORMAL);
    box(win, 0, 0);
    if (!title.empty()) {
        mvwprintw(win, 0, 2, " %s ", title.c_str());
    }
    wattroff(win, active ? A_BOLD : A_NORMAL);
}

static std::string prompt_input(WINDOW* win, int y, int x, const std::string& prompt) {
    mvwprintw(win, y, x, "%s", prompt.c_str());
    wrefresh(win);
    echo();
    curs_set(1);
    char buf[256];
    memset(buf, 0, sizeof(buf));
    wgetnstr(win, buf, sizeof(buf) - 1);
    noecho();
    curs_set(0);
    return std::string(buf);
}

static bool confirm_dialog(const std::string& msg) {
    WINDOW* win = newwin(5, 50, (LINES - 5) / 2, (COLS - 50) / 2);
    box(win, 0, 0);
    mvwprintw(win, 1, 2, "%s", msg.c_str());
    mvwprintw(win, 3, 2, "[y/N]");
    wrefresh(win);
    int ch = wgetch(win);
    delwin(win);
    return (ch == 'y' || ch == 'Y');
}

void run_tui(Database& db, Config& cfg) {
    initscr();
    raw();
    noecho();
    keypad(stdscr, TRUE);
    curs_set(0);
    start_color();
    use_default_colors();

    init_pair(1, COLOR_YELLOW, -1);
    init_pair(2, COLOR_CYAN, -1);
    init_pair(3, COLOR_RED, -1);

    TuiState state;
    state.sel_date = current_date();
    state.cal_month = state.sel_date.month;
    state.cal_year = state.sel_date.year;
    state.active_panel = static_cast<ActivePanel>(cfg.default_panel);

    // Write lock file
    std::string pid_file = db.datadir + "/.calcurse.pid";
    std::ofstream pofs(pid_file);
    if (pofs.is_open()) pofs << getpid() << "\n";
    pofs.close();

    while (!state.quit) {
        int max_y = LINES, max_x = COLS;
        erase();

        int status_h = 2;
        int notify_h = cfg.notify_bar ? 1 : 0;
        int main_h = max_y - status_h - notify_h;

        int cal_w = max_x / 3;
        int apt_w = max_x - cal_w;
        int todo_h = main_h / 2;
        int apt_h = main_h - todo_h;

        WINDOW* win_cal = newwin(main_h / 2, cal_w, 0, 0);
        WINDOW* win_todo = newwin(main_h - (main_h / 2), cal_w, main_h / 2, 0);
        WINDOW* win_apt = newwin(main_h, apt_w, 0, cal_w);
        WINDOW* win_notify = notify_h ? newwin(notify_h, max_x, main_h, 0) : nullptr;
        WINDOW* win_status = newwin(status_h, max_x, main_h + notify_h, 0);

        // Draw Calendar Panel
        draw_border_title(win_cal, "Calendar", state.active_panel == PANEL_CALENDAR);
        mvwprintw(win_cal, 1, 2, "%02d/%04d", state.cal_month, state.cal_year);
        mvwprintw(win_cal, 2, 2, "Mo Tu We Th Fr Sa Su");
        Date first_day{state.cal_year, state.cal_month, 1};
        int start_dow = (day_of_week(first_day) + 6) % 7; // Monday = 0
        int dim = days_in_month(state.cal_month, state.cal_year);

        int cur_row = 3, cur_col = start_dow;
        for (int d = 1; d <= dim; ++d) {
            bool is_sel = (d == state.sel_date.day && state.cal_month == state.sel_date.month && state.cal_year == state.sel_date.year);
            if (is_sel) wattron(win_cal, A_REVERSE);
            mvwprintw(win_cal, cur_row, 2 + cur_col * 3, "%2d", d);
            if (is_sel) wattroff(win_cal, A_REVERSE);

            cur_col++;
            if (cur_col >= 7) {
                cur_col = 0;
                cur_row++;
            }
        }
        wrefresh(win_cal);

        // Draw Apt Panel
        draw_border_title(win_apt, "Appointments", state.active_panel == PANEL_APTS);
        std::string date_str = format_date(state.sel_date, "%A %B %d, %Y");
        mvwprintw(win_apt, 1, 2, "--- %s ---", date_str.c_str());

        std::vector<EventItem> day_events;
        for (const auto& e : db.events) {
            if (e.recur.occurs_on(state.sel_date, e.day)) day_events.push_back(e);
        }
        std::vector<AptItem> day_apts;
        for (const auto& a : db.apts) {
            if (a.recur.occurs_on(state.sel_date, a.start.date)) day_apts.push_back(a);
        }

        int apt_row = 3;
        for (const auto& e : day_events) {
            mvwprintw(win_apt, apt_row++, 2, " * %s", e.mesg.c_str());
        }
        for (size_t idx = 0; idx < day_apts.size(); ++idx) {
            const auto& a = day_apts[idx];
            bool is_sel = (state.active_panel == PANEL_APTS && static_cast<int>(idx) == state.sel_apt_idx);
            if (is_sel) wattron(win_apt, A_REVERSE);
            mvwprintw(win_apt, apt_row++, 2, " - %s -> %s: %s",
                      format_time(a.start.time).c_str(),
                      format_time(a.end.time).c_str(),
                      a.mesg.c_str());
            if (is_sel) wattroff(win_apt, A_REVERSE);
        }
        wrefresh(win_apt);

        // Draw Todo Panel
        draw_border_title(win_todo, "ToDo", state.active_panel == PANEL_TODO);
        int todo_row = 1;
        for (size_t idx = 0; idx < db.todos.size(); ++idx) {
            const auto& t = db.todos[idx];
            bool is_sel = (state.active_panel == PANEL_TODO && static_cast<int>(idx) == state.sel_todo_idx);
            if (is_sel) wattron(win_todo, A_REVERSE);
            mvwprintw(win_todo, todo_row++, 2, "%d. %s", t.priority, t.mesg.c_str());
            if (is_sel) wattroff(win_todo, A_REVERSE);
        }
        wrefresh(win_todo);

        // Draw Notify Bar
        if (win_notify) {
            DateTime now = current_datetime();
            mvwprintw(win_notify, 0, 1, "%s | %s | %s",
                      format_datetime(now, cfg.notify_datefmt).c_str(),
                      format_datetime(now, cfg.notify_timefmt).c_str(),
                      db.calendar_file.empty() ? "apts" : db.calendar_file.c_str());
            wrefresh(win_notify);
        }

        // Draw Status Bar
        mvwprintw(win_status, 0, 1, " ? Help   R Redraw   H/L -/+1 Day   G GoTo     C Config");
        mvwprintw(win_status, 1, 1, " Q Quit   S Save     J/K -/+1 Week  Tab Chg View  a Add  d Del");
        wrefresh(win_status);

        // Input loop
        int ch = wgetch(win_cal);
        switch (ch) {
            case 'q':
            case 'Q':
                if (!cfg.confirm_quit || confirm_dialog("Do you really want to quit?")) {
                    if (cfg.auto_save) db.save_all();
                    state.quit = true;
                }
                break;
            case 's':
            case 'S':
                db.save_all();
                break;
            case '\t':
            case 9:
                state.active_panel = static_cast<ActivePanel>((state.active_panel + 1) % 3);
                break;
            case 'h':
            case 'H':
            case KEY_LEFT:
                state.sel_date = days_to_date(date_to_days(state.sel_date) - 1);
                state.cal_month = state.sel_date.month;
                state.cal_year = state.sel_date.year;
                break;
            case 'l':
            case 'L':
            case KEY_RIGHT:
                state.sel_date = days_to_date(date_to_days(state.sel_date) + 1);
                state.cal_month = state.sel_date.month;
                state.cal_year = state.sel_date.year;
                break;
            case 'j':
            case 'J':
            case KEY_DOWN:
                if (state.active_panel == PANEL_CALENDAR) {
                    state.sel_date = days_to_date(date_to_days(state.sel_date) + 7);
                    state.cal_month = state.sel_date.month;
                    state.cal_year = state.sel_date.year;
                } else if (state.active_panel == PANEL_APTS) {
                    if (state.sel_apt_idx + 1 < static_cast<int>(day_apts.size())) state.sel_apt_idx++;
                } else if (state.active_panel == PANEL_TODO) {
                    if (state.sel_todo_idx + 1 < static_cast<int>(db.todos.size())) state.sel_todo_idx++;
                }
                break;
            case 'k':
            case 'K':
            case KEY_UP:
                if (state.active_panel == PANEL_CALENDAR) {
                    state.sel_date = days_to_date(date_to_days(state.sel_date) - 7);
                    state.cal_month = state.sel_date.month;
                    state.cal_year = state.sel_date.year;
                } else if (state.active_panel == PANEL_APTS) {
                    if (state.sel_apt_idx > 0) state.sel_apt_idx--;
                } else if (state.active_panel == PANEL_TODO) {
                    if (state.sel_todo_idx > 0) state.sel_todo_idx--;
                }
                break;
            case 'a':
            case 1: // Ctrl+A
                if (state.active_panel == PANEL_TODO) {
                    std::string desc = prompt_input(win_status, 0, 1, "Enter description: ");
                    if (!desc.empty()) {
                        std::string p_str = prompt_input(win_status, 0, 1, "Enter priority (1-9): ");
                        int prio = p_str.empty() ? 1 : std::stoi(p_str);
                        TodoItem t;
                        t.priority = prio;
                        t.mesg = desc;
                        t.raw_line = t.to_raw_line();
                        t.hash = compute_sha1(t.raw_line);
                        db.todos.push_back(t);
                    }
                } else if (state.active_panel == PANEL_APTS) {
                    std::string start_str = prompt_input(win_status, 0, 1, "Enter start time ([hh:mm] or Enter for event): ");
                    if (start_str.empty()) {
                        std::string desc = prompt_input(win_status, 0, 1, "Enter event description: ");
                        if (!desc.empty()) {
                            EventItem e;
                            e.day = state.sel_date;
                            e.mesg = desc;
                            e.raw_line = e.to_raw_line(db.input_fmt);
                            e.hash = compute_sha1(e.raw_line);
                            db.events.push_back(e);
                        }
                    } else {
                        std::string dur_str = prompt_input(win_status, 0, 1, "Enter end time [hh:mm]: ");
                        std::string desc = prompt_input(win_status, 0, 1, "Enter description: ");
                        if (!desc.empty()) {
                            AptItem a;
                            a.start.date = state.sel_date;
                            parse_time_str(start_str, a.start.time);
                            a.end.date = state.sel_date;
                            parse_time_str(dur_str, a.end.time);
                            a.mesg = desc;
                            a.raw_line = a.to_raw_line(db.input_fmt);
                            a.hash = compute_sha1(a.raw_line);
                            db.apts.push_back(a);
                        }
                    }
                }
                break;
            case 'd':
            case 4: // Ctrl+D
            case KEY_DC:
                if (!cfg.confirm_delete || confirm_dialog("Do you really want to delete this item?")) {
                    if (state.active_panel == PANEL_TODO && !db.todos.empty() && state.sel_todo_idx < static_cast<int>(db.todos.size())) {
                        db.todos.erase(db.todos.begin() + state.sel_todo_idx);
