            case 'G': {
                std::string date_inp = prompt_input(win_status, 0, 1, "Enter date: ");
                Date d;
                if (parse_date_str(date_inp, cfg.input_datefmt, d)) {
                    state.sel_date = d;
                    state.cal_month = d.month;
                    state.cal_year = d.year;
                }
                break;
            }
            default:
                break;
        }

        delwin(win_cal);
        delwin(win_todo);
        delwin(win_apt);
        if (win_notify) delwin(win_notify);
        delwin(win_status);
    }

    unlink(pid_file.c_str());
    endwin();
}
