              << "  --days <number>         Limit day range of -Q.\n\n"
              << "  --limit, -l <number>    Limit number of query results\n"
              << "  --search, -S <regexp>   Match regular expression in queries\n"
              << "Consult the man page for details.\n\n"
              << "Miscellaneous:\n"
              << "  -c, --calendar <file>   The calendar data file to use\n"
              << "  -C, --confdir <dir>     The configuration directory to use\n"
              << "  --daemon                Run notification daemon in the background\n"
              << "  -D, --datadir <dir>     The data directory to use\n"
              << "  -g, --gc                Run the garbage collector\n"
              << "  -h, --help              Show this help text\n"
              << "  -i, --import <file>     Import iCal data from file\n"
              << "  -q, --quiet             Suppress import/export result message\n"
              << "  --read-only             Do not save configuration or data files\n"
              << "  --status                Display status of running instances\n"
              << "  -v, --version           Show version information\n"
              << "  -x, --export[<format>]  Export to stdout in ical (default) or pcal format\n\n"
              << "For more information, type '?' from within calcurse, or read the manpage.\n"
              << "Submit feature requests and suggestions to <misc@calcurse.org>.\n"
              << "Submit bug reports to <bugs@calcurse.org>.\n";
}

int main(int argc, char* argv[]) {
    std::string datadir, confdir, calendar_file;
    const char* home = getenv("HOME");
    std::string home_str = home ? home : "";

    std::string dot_calcurse = home_str + "/.calcurse";
    if (!home_str.empty() && fs::exists(dot_calcurse)) {
        datadir = dot_calcurse;
        confdir = dot_calcurse;
    } else {
        const char* xdg_data = getenv("XDG_DATA_HOME");
        const char* xdg_conf = getenv("XDG_CONFIG_HOME");
        datadir = (xdg_data && *xdg_data) ? (std::string(xdg_data) + "/calcurse") : (home_str + "/.local/share/calcurse");
        confdir = (xdg_conf && *xdg_conf) ? (std::string(xdg_conf) + "/calcurse") : (home_str + "/.config/calcurse");
    }

    enum Mode { MODE_INTERACTIVE, MODE_QUERY, MODE_GREP, MODE_PURGE, MODE_GC, MODE_IMPORT, MODE_EXPORT, MODE_STATUS, MODE_DAEMON, MODE_NEXT };
    Mode mode = MODE_INTERACTIVE;

    bool quiet = false;
    bool read_only = false;
    bool dump_imported = false;
    std::string import_file;
    std::string export_fmt = "ical";

    FilterOpts filters;
    FormatOpts formats;

    Date query_from{0, 0, 0};
    Date query_to{0, 0, 0};
    int query_days = 0;
    bool query_days_set = false;
    int limit = -1;
    int todo_prio_query = -1;

    static struct option long_options[] = {
        {"calendar", required_argument, 0, 'c'},
        {"confdir", required_argument, 0, 'C'},
        {"daemon", no_argument, 0, 1000},
        {"datadir", required_argument, 0, 'D'},
        {"days", required_argument, 0, 1001},
        {"dump-imported", no_argument, 0, 1002},
        {"export", optional_argument, 0, 'x'},
        {"from", required_argument, 0, 1003},
        {"gc", no_argument, 0, 'g'},
        {"grep", no_argument, 0, 'G'},
        {"help", no_argument, 0, 'h'},
        {"import", required_argument, 0, 'i'},
        {"input-datefmt", required_argument, 0, 1004},
        {"limit", required_argument, 0, 'l'},
        {"next", no_argument, 0, 'n'},
        {"output-datefmt", required_argument, 0, 1005},
        {"purge", no_argument, 0, 'P'},
        {"query", no_argument, 0, 'Q'},
        {"quiet", no_argument, 0, 'q'},
        {"range", optional_argument, 0, 'r'},
        {"read-only", no_argument, 0, 1006},
        {"search", required_argument, 0, 'S'},
        {"startdate", optional_argument, 0, 's'},
        {"status", no_argument, 0, 1007},
        {"to", required_argument, 0, 1008},
        {"todo", optional_argument, 0, 't'},
        {"version", no_argument, 0, 'v'},
        {"appointment", no_argument, 0, 'a'},
        {"day", required_argument, 0, 'd'},
        {"filter-type", required_argument, 0, 1100},
        {"filter-pattern", required_argument, 0, 1101},
        {"filter-hash", required_argument, 0, 1102},
        {"filter-start-from", required_argument, 0, 1103},
        {"filter-start-to", required_argument, 0, 1104},
        {"filter-start-after", required_argument, 0, 1105},
        {"filter-start-before", required_argument, 0, 1106},
        {"filter-start-range", required_argument, 0, 1107},
        {"filter-end-from", required_argument, 0, 1108},
        {"filter-end-to", required_argument, 0, 1109},
        {"filter-end-after", required_argument, 0, 1110},
        {"filter-end-before", required_argument, 0, 1111},
        {"filter-end-range", required_argument, 0, 1112},
        {"filter-priority", required_argument, 0, 1113},
        {"filter-completed", no_argument, 0, 1114},
        {"filter-uncompleted", no_argument, 0, 1115},
        {"filter-invert", no_argument, 0, 1116},
        {"format-apt", required_argument, 0, 1200},
        {"format-recur-apt", required_argument, 0, 1201},
        {"format-event", required_argument, 0, 1202},
        {"format-recur-event", required_argument, 0, 1203},
        {"format-todo", required_argument, 0, 1204},
        {0, 0, 0, 0}
    };

    int input_fmt_override = -1;
    std::string output_fmt_override;

    int opt;
    while ((opt = getopt_long(argc, argv, "aC:c:D:d:gGhi:l:nPQqS:s:t:vx::r::", long_options, nullptr)) != -1) {
        switch (opt) {
            case 'v':
                print_version();
                return 0;
            case 'h':
                print_usage();
                return 0;
            case 1007: // --status
                mode = MODE_STATUS;
                break;
            case 1000: // --daemon
                mode = MODE_DAEMON;
                break;
            case 'D':
                datadir = optarg;
                break;
            case 'C':
                confdir = optarg;
                break;
            case 'c':
                calendar_file = optarg;
                break;
            case 'q':
                quiet = true;
                break;
            case 1006: // --read-only
                read_only = true;
                break;
            case 1004: // --input-datefmt
                input_fmt_override = std::stoi(optarg);
                break;
            case 1005: // --output-datefmt
                output_fmt_override = optarg;
                break;
            case 'i':
                mode = MODE_IMPORT;
                import_file = optarg;
                break;
            case 1002: // --dump-imported
                dump_imported = true;
                break;
            case 'x':
                mode = MODE_EXPORT;
                if (optarg) export_fmt = optarg;
                break;
            case 'g':
                mode = MODE_GC;
                break;
            case 'G':
                mode = MODE_GREP;
                break;
            case 'P':
                mode = MODE_PURGE;
                break;
            case 'Q':
                mode = MODE_QUERY;
                break;
            case 'a':
                mode = MODE_QUERY;
                filters.set_type_filter("cal");
                query_from = current_date();
                query_days = 1;
                query_days_set = true;
                break;
            case 'd': {
                mode = MODE_QUERY;
                filters.set_type_filter("cal");
                std::string arg = optarg;
                Date d;
                int ifmt = (input_fmt_override > 0) ? input_fmt_override : 1;
                if (parse_date_str(arg, ifmt, d)) {
                    query_from = d;
                    query_days = 1;
                    query_days_set = true;
                } else {
                    int num = std::stoi(arg);
                    query_from = current_date();
                    query_days = num;
                    query_days_set = true;
                }
                break;
            }
            case 'n':
                mode = MODE_NEXT;
                break;
            case 'r':
                mode = MODE_QUERY;
                filters.set_type_filter("cal");
                query_from = current_date();
                query_days = optarg ? std::stoi(optarg) : 1;
                query_days_set = true;
                break;
            case 's':
                mode = MODE_QUERY;
                filters.set_type_filter("cal");
                if (optarg) {
                    int ifmt = (input_fmt_override > 0) ? input_fmt_override : 1;
                    parse_date_str(optarg, ifmt, query_from);
                } else {
                    query_from = current_date();
                }
                if (!query_days_set) { query_days = 1; query_days_set = true; }
                break;
            case 't':
                mode = MODE_QUERY;
                filters.set_type_filter("todo");
                if (optarg) todo_prio_query = std::stoi(optarg);
                break;
            case 'l':
                limit = std::stoi(optarg);
                break;
            case 'S':
                filters.pattern = optarg;
                break;
            case 1003: // --from
                if (parse_date_str(optarg, input_fmt_override > 0 ? input_fmt_override : 1, query_from)) {
                } else {
                    std::cerr << "args.c: 797: invalid date: " << optarg << "\n";
                    return 1;
                }
                break;
            case 1008: // --to
                parse_date_str(optarg, input_fmt_override > 0 ? input_fmt_override : 1, query_to);
                break;
            case 1001: // --days
                query_days = std::stoi(optarg);
                query_days_set = true;
                break;
            case 1100: // --filter-type
                filters.set_type_filter(optarg);
                break;
            case 1101: // --filter-pattern
                filters.pattern = optarg;
                break;
            case 1102: // --filter-hash
                if (optarg[0] == '!') {
                    filters.hash_invert = true;
                    filters.hash_str = std::string(optarg + 1);
                } else {
                    filters.hash_invert = false;
                    filters.hash_str = optarg;
                }
                break;
            case 1113: // --filter-priority
                filters.priority = std::stoi(optarg);
                break;
            case 1114: // --filter-completed
                filters.completed = true;
                break;
            case 1115: // --filter-uncompleted
                filters.uncompleted = true;
                break;
            case 1116: // --filter-invert
                filters.invert = true;
                break;
            case 1200: // --format-apt
                formats.fmt_apt = optarg; formats.custom_apt = true; break;
            case 1201: // --format-recur-apt
                formats.fmt_recur_apt = optarg; formats.custom_recur_apt = true; break;
            case 1202: // --format-event
                formats.fmt_event = optarg; formats.custom_event = true; break;
            case 1203: // --format-recur-event
                formats.fmt_recur_event = optarg; formats.custom_recur_event = true; break;
            case 1204: // --format-todo
                formats.fmt_todo = optarg; formats.custom_todo = true; break;
            default:
                print_usage();
                return 1;
        }
    }

    Config cfg;
    fs::create_directories(confdir);
    cfg.load(confdir + "/conf");
    if (input_fmt_override > 0) cfg.input_datefmt = input_fmt_override;
    if (!output_fmt_override.empty()) cfg.output_datefmt = output_fmt_override;

    Database db;
    db.set_paths(datadir, confdir, calendar_file);
    db.read_only = read_only;
    db.input_fmt = cfg.input_datefmt;
    db.load_all();

    if (mode == MODE_STATUS) {
        return check_status(db);
    }
    if (mode == MODE_DAEMON) {
        run_daemon(db, cfg);
        return 0;
    }
    if (mode == MODE_GC) {
        db.gc_notes();
        return 0;
    }
    if (mode == MODE_IMPORT) {
        ImportReport report;
        if (formats.is_raw() && !formats.custom_apt) formats.fmt_apt = "%(raw)";
        if (formats.is_raw() && !formats.custom_todo) formats.fmt_todo = "%(raw)";
        if (formats.is_raw() && !formats.custom_event) formats.fmt_event = "%(raw)";

        if (import_ical(import_file, db, report, dump_imported, formats, quiet)) {
            if (!read_only) db.save_all();
            return 0;
        }
        return 1;
    }
    if (mode == MODE_EXPORT) {
        if (export_fmt == "pcal") {
            export_pcal(db, filters, std::cout);
        } else {
            export_ical(db, filters, std::cout);
        }
        return 0;
    }
    if (mode == MODE_GREP) {
        if (!formats.custom_apt) formats.fmt_apt = "%(raw)";
        if (!formats.custom_event) formats.fmt_event = "%(raw)";
        if (!formats.custom_todo) formats.fmt_todo = "%(raw)";

        for (const auto& item : db.todos) {
            if (filters.match_todo(item)) std::cout << format_todo(item, formats.fmt_todo, db);
        }
        for (const auto& item : db.events) {
            if (filters.match_event(item)) std::cout << format_event(item, formats.fmt_event, db);
        }
        for (const auto& item : db.apts) {
            if (filters.match_apt(item)) std::cout << format_apt(item, item.start.date, formats.fmt_apt, db);
        }
        return 0;
    }
    if (mode == MODE_PURGE) {
        auto new_todos = db.todos;
        db.todos.clear();
        for (const auto& item : new_todos) {
            if (!filters.match_todo(item)) db.todos.push_back(item);
        }
        auto new_events = db.events;
        db.events.clear();
        for (const auto& item : new_events) {
            if (!filters.match_event(item)) db.events.push_back(item);
        }
        auto new_apts = db.apts;
        db.apts.clear();
        for (const auto& item : new_apts) {
            if (!filters.match_apt(item)) db.apts.push_back(item);
        }
        if (!read_only) db.save_all();
        return 0;
    }
    if (mode == MODE_NEXT) {
        DateTime now = current_datetime();
        AptItem best_apt;
        bool found = false;
        long min_diff_sec = 86400;

        for (const auto& apt : db.apts) {
            if (apt.recur.occurs_on(now.date, apt.start.date)) {
                if (apt.start.date == now.date) {
                    long diff = (apt.start.time.hour * 60 + apt.start.time.minute) - (now.time.hour * 60 + now.time.minute);
                    if (diff >= 0 && diff * 60 < min_diff_sec) {
                        min_diff_sec = diff * 60;
                        best_apt = apt;
                        found = true;
                    }
                }
            }
        }
        if (found) {
            int h = min_diff_sec / 3600;
            int m = (min_diff_sec % 3600) / 60;
            char buf[64];
            snprintf(buf, sizeof(buf), "next appointment:\n   [%02d:%02d] %s\n", h, m, best_apt.mesg.c_str());
            std::cout << buf;
        }
        return 0;
    }

    if (mode == MODE_QUERY) {
        int printed_count = 0;

        // Todos in query
        if (filters.type_todo) {
            std::vector<TodoItem> match_todos;
            for (const auto& item : db.todos) {
                if (filters.match_todo(item)) {
                    if (todo_prio_query == 0) {
                        if (item.completed) match_todos.push_back(item);
                    } else if (todo_prio_query > 0) {
                        if (!item.completed && item.priority == todo_prio_query) match_todos.push_back(item);
                    } else {
                        if (!item.completed) match_todos.push_back(item);
                    }
                }
            }
            if (!match_todos.empty()) {
                if (todo_prio_query == 0) std::cout << "completed tasks:\n";
                else std::cout << "to do:\n";

                for (const auto& item : match_todos) {
                    if (limit >= 0 && printed_count >= limit) break;
                    std::cout << format_todo(item, formats.fmt_todo, db);
                    printed_count++;
                }
            }
        }

        // Days range in query
        if (query_from.year > 0) {
            Date start_d = query_from;
            Date end_d = query_from;
            if (query_to.year > 0) {
                end_d = query_to;
            } else if (query_days_set) {
                if (query_days > 0) {
                    end_d = days_to_date(date_to_days(query_from) + query_days - 1);
                } else if (query_days < 0) {
                    start_d = days_to_date(date_to_days(query_from) + query_days + 1);
                    end_d = query_from;
                }
            }

            int day_start = date_to_days(start_d);
            int day_end = date_to_days(end_d);

            for (int d = day_start; d <= day_end; ++d) {
                if (limit >= 0 && printed_count >= limit) break;
                Date cur_d = days_to_date(d);

                std::vector<EventItem> day_events;
                for (const auto& item : db.events) {
                    if (filters.match_event(item) && item.recur.occurs_on(cur_d, item.day)) {
                        day_events.push_back(item);
                    }
                }

                std::vector<AptItem> day_apts;
                for (const auto& item : db.apts) {
                    if (filters.match_apt(item) && item.recur.occurs_on(cur_d, item.start.date)) {
                        day_apts.push_back(item);
                    }
                }

                if (!day_events.empty() || !day_apts.empty()) {
                    if (printed_count > 0 || filters.type_todo) std::cout << "\n";
                    std::cout << format_date(cur_d, cfg.output_datefmt) << ":\n";

                    for (const auto& item : day_events) {
                        if (limit >= 0 && printed_count >= limit) break;
                        std::cout << format_event(item, formats.fmt_event, db);
                        printed_count++;
                    }
                    for (const auto& item : day_apts) {
                        if (limit >= 0 && printed_count >= limit) break;
                        std::cout << format_apt(item, cur_d, formats.fmt_apt, db);
                        printed_count++;
                    }
                }
            }
        }
        return 0;
    }

    // Interactive TUI mode
    run_tui(db, cfg);
    return 0;
}
EOF"}
